from units import average


def make_report(city, readings):
    temperature = average(readings)
    if temperature >= 25:
        label = "warm"
    else:
        label = "mild"
    return f"{city}: {temperature:.1f} C, {label}"

def average(values):
    if not values:
        return 0
    return sum(values) / len(values)
